3	// XoroShiro128+ with a=24, b=16, c=37,
4	// - https://en.wikipedia.org/wiki/Xoroshiro128%2B
5	// - http://prng.di.unimi.it/xoroshiro128plus.c
6	class XoroShiro128Plus implements JumpableRandomGenerator {
7	  constructor(
8	    private s01: number,
9	    private s00: number,
10	    private s11: number,
11	    private s10: number,
12	  ) {}
13	  clone(): XoroShiro128Plus {
14	    return new XoroShiro128Plus(this.s01, this.s00, this.s11, this.s10);
15	  }
16	  next(): number {
17	    const out = (this.s00 + this.s10) | 0;
18	    // a = s0[n] ^ s1[n]
19	    const a0 = this.s10 ^ this.s00;
20	    const a1 = this.s11 ^ this.s01;
21	    const s00 = this.s00;
22	    const s01 = this.s01;
23	    // s0[n+1] = rotl(s0[n], 24) ^ a ^ (a << 16)
24	    this.s00 = (s00 << 24) ^ (s01 >>> 8) ^ a0 ^ (a0 << 16);
25	    this.s01 = (s01 << 24) ^ (s00 >>> 8) ^ a1 ^ ((a1 << 16) | (a0 >>> 16));
26	    // s1[n+1] = rotl(a, 37)
27	    this.s10 = (a1 << 5) ^ (a0 >>> 27);
28	    this.s11 = (a0 << 5) ^ (a1 >>> 27);
29	    return out;
30	  }
31	  jump(): void {
32	    // equivalent to 2^64 calls to next()
33	    // can be used to generate 2^64 non-overlapping subsequences
34	    let ns01 = 0;
35	    let ns00 = 0;
36	    let ns11 = 0;
37	    let ns10 = 0;
38	    const jump = [0xd8f554a5, 0xdf900294, 0x4b3201fc, 0x170865df];
39	    for (let i = 0; i !== 4; ++i) {
40	      for (let mask = 1; mask; mask <<= 1) {
41	        // Because: (1 << 31) << 1 === 0
42	        if (jump[i] & mask) {
43	          ns01 ^= this.s01;
44	          ns00 ^= this.s00;
45	          ns11 ^= this.s11;
46	          ns10 ^= this.s10;
47	        }
48	        this.next();
49	      }
50	    }
51	    this.s01 = ns01;
52	    this.s00 = ns00;
53	    this.s11 = ns11;
54	    this.s10 = ns10;
55	  }
56	  getState(): readonly number[] {
57	    return [this.s01, this.s00, this.s11, this.s10];
58	  }
59	}
